				backend_Conductor.set_bpm(states_PlayState.SONG.notes[this.curSection].bpm);
				this.setOnScripts("curBpm",backend_Conductor.bpm);
				this.setOnScripts("crochet",backend_Conductor.crochet);
				this.setOnScripts("stepCrochet",backend_Conductor.stepCrochet);
