	,getSelected: function(blockReserved) {
		if(blockReserved == null) {
			blockReserved = true;
		}
		var selected = this.host.spriteListRadioGroup.checked;
		if(selected >= 0) {
			var spr = this.host.stageSprites[this.host.spriteListRadioGroup.labels.length - selected - 1];
			if(spr != null && (!blockReserved || backend_StageData.reservedNames.indexOf(spr.type) == -1)) {
				return spr;
			}
		}
		return null;
	}
