	,opponentNoteHit: function(note) {
		if(states_PlayState.SONG.needsVoices && this.opponentVocals._length <= 0) {
			this.vocals.set_volume(1);
		}
		var strum = this.opponentStrums.members[Math.abs(note.noteData) | 0];
		if(strum != null) {
			strum.playAnim("confirm",true);
			strum.resetAnim = backend_Conductor.stepCrochet * 1.25 / 1000 / this.playbackRate;
		}
		note.hitByOpponent = true;
		this.spawnHoldSplashOnNote(note);
		if(!note.isSustainNote) {
			this.invalidateNote(note);
		}
	}
	,goodNoteHit: function(note) {
		if(note.wasGoodHit) {
			return;
		}
		note.wasGoodHit = true;
		if(note.get_hitsoundVolume() > 0 && !note.hitsoundDisabled) {
			flixel_FlxG.sound.play(backend_Paths.returnSound("sounds/" + note.hitsound,null,true),note.get_hitsoundVolume());
		}
		if(note.hitCausesMiss) {
			this.noteMiss(note);
			if(!note.noteSplashData.disabled && !note.isSustainNote) {
				this.spawnNoteSplashOnNote(note);
			}
			if(!note.isSustainNote) {
				this.invalidateNote(note);
			}
			return;
		}
		if(!note.isSustainNote) {
			this.combo++;
			if(this.combo > 9999) {
				this.combo = 9999;
			}
			this.popUpScore(note);
		}
		var spr = this.playerStrums.members[note.noteData];
		if(spr != null) {
			spr.playAnim("confirm",true);
		}
		this.vocals.set_volume(1);
		this.spawnHoldSplashOnNote(note);
		if(!note.isSustainNote) {
			this.invalidateNote(note);
		}
		this.updateScore();
	}
